// Photonic Landing's seven-stop spectrum and converging fibre geometry.
const SPECTRUM=[[255,75,62],[255,154,43],[255,216,77],[77,255,122],[61,213,255],[74,107,255],[162,77,255]];
const PHASES={queued:['等待线索','Watching'],collect:['收集信息','Collecting'],verify:['交叉比对','Cross-checking'],queuedCore:['等待汇总','Queued for review'],core:['汇聚判断','Reviewing'],complete:['研究完成','Research complete']};
