// The coordinator has already validated the report DTO. Bind its presentation to
// the current identity, asset and original request; it does not advance model roles.
export function photonicResearchJobView(task,job,identity,now=Date.now()){
 const clock=value=>Number.isSafeInteger(value)&&value>=0;
 if(task?.mode!=='live_readonly'||job?.mode!=='live_readonly'||job.executionAuthority!=='NONE'||!clock(now)||
  typeof identity?.ownerRef!=='string'||!/^[A-Za-z0-9:_@.\-]{1,256}$/.test(identity.ownerRef)||job.ownerRef!==identity.ownerRef||!clock(identity.expiresAt)||identity.expiresAt<=now||
  typeof job.requestId!=='string'||!/^[A-Za-z0-9:_-]{8,96}$/.test(job.requestId)||!clock(job.createdAt)||job.createdAt>now||
  !Array.isArray(job.symbols)||job.symbols.length!==1||job.symbols[0]!==task.symbol)return null;
 let status=job.status,headline='';
 if(['complete','expired'].includes(status)){
  const result=job.result,source=result?.sources?.[0],output=result?.output;
  if(result?.method!=='ai'||result.executionAuthority!=='NONE'||result.methodVersion!=='closed-market-research-v1'||
   !clock(result.createdAt)||result.createdAt>now||!clock(result.validUntil)||result.validUntil<=result.createdAt||
   !Array.isArray(result.sources)||result.sources.length!==1||source?.symbol!==task.symbol||!Number.isFinite(source.validUntil)||source.validUntil*1000!==result.validUntil||
   !['watch','conflict','insufficient'].includes(output?.outcome)||typeof output.headline!=='string'||!output.headline.trim()||output.headline.length>120||/[\u0000-\u001f\u007f]/.test(output.headline))return null;
  if(result.validUntil<=now)status='expired';
  if(status==='complete')headline=output.headline;
 }else if(status==='service-unavailable'){
  // The existing client uses this status for both a confirmed failed record and
  // transport/admission errors. An unresolved original request stays unconfirmed.
  if(job.queryOriginalRequest===true)status='unknown';
  else if(job.queryOriginalRequest===false&&typeof job.error==='string'&&/^[A-Z][A-Z0-9_]{1,63}$/.test(job.error))status='failed';
  else return null;
 }else if(!['processing','unknown'].includes(status)||job.queryOriginalRequest!==true)return null;
 const labels={processing:['AI 研究进行中','AI research in progress'],complete:['AI 研究完成','AI research complete'],failed:['AI 研究失败','AI research failed'],unknown:['原请求待确认','Original request unconfirmed'],expired:['AI 报告已过期','AI report expired']};
 const words={processing:['分析','Analyze'],failed:['失败','Failed'],unknown:['待确认','Confirm'],expired:['已过期','Expired']};
 const word=status==='complete'?{watch:['观察','Watch'],conflict:['分歧','Conflict'],insufficient:['待证','Evidence']}[job.result.output.outcome]:words[status];
 const label=L(...labels[status]);
 return {status,requestId:job.requestId,word:L(...word),label,heading:`${task.symbol} · ${label}`,headline,
  signature:JSON.stringify([job.ownerRef,job.requestId,job.createdAt,status,job.result?.createdAt,job.result?.validUntil,job.result?.output?.outcome,headline])};
}
