export function prismLabelSize(width,height,emWidth){
 return Math.min(height*.12,width*.16,width*.36/Math.max(.1,emWidth));
}

export function prismDragRotation(start,dx,dy){
 return {yaw:Math.max(-.85,Math.min(.85,start.yaw+dx*.008)),pitch:Math.max(-.4,Math.min(.4,start.pitch+dy*.006))};
}

export function prismLocalRect(prism,canvas){
 if(prism.width<2||prism.height<2||canvas.width<2||canvas.height<2)return null;
 return {left:prism.left-canvas.left,top:prism.top-canvas.top,width:prism.width,height:prism.height,right:prism.left-canvas.left+prism.width};
}

export function createPhotonicRenderGate(panels,optics,render,onEnter){
 const visible=new Set();let chart=null,timer=0,disposed=false;
 const canRender=()=>!disposed&&!document.hidden&&(panels.some(node=>visible.has(node))||chart&&visible.has(chart));
 const request=()=>{if(timer||!canRender())return;timer=setTimeout(()=>{timer=0;if(canRender())render();},0);};
 const observer=new IntersectionObserver(entries=>{
  for(const entry of entries){if(entry.isIntersecting)visible.add(entry.target);else visible.delete(entry.target);}
  if(visible.has(optics))onEnter();request();
 });
 for(const node of [...panels,optics])observer.observe(node);
 return {request,
  watchChart(node){if(node===chart)return;if(chart){observer.unobserve(chart);visible.delete(chart);}chart=node;if(chart)observer.observe(chart);},
  get opticsVisible(){return visible.has(optics);},get analysisVisible(){return Boolean(chart&&visible.has(chart));},
  dispose(){disposed=true;clearTimeout(timer);observer.disconnect();visible.clear();}
 };
}

